def gen_actions(tok):
    acts=[]
    # each bit: keep,0,1
    for hg in itertools.product([None,0,1], repeat=3):
        # natural constraints
        if tok=="G" and hg[0] not in (None,1): continue
        if tok=="NG" and hg[0] not in (None,0): continue
        if tok=="H" and hg[1]!=1: continue
        if tok=="NH" and hg[1]!=0: continue
        if tok=="B" and hg[2]!=1: continue
        if tok=="NB" and hg[2]!=0: continue
        # G/NG maybe only set h/b to same as g if set
        out=[]
        for s in states:
            ns=tuple(hg[i] if hg[i] is not None else s[i] for i in range(3))
            out.append(state_index(ns))
        acts.append((hg,tuple(out)))
    return acts

token_list=list(tokens.keys())
acts={t:gen_actions(t) for t in token_list}
print({t:len(v) for t,v in acts.items()})

solutions=[]
count=0
for init in states:
    # pre filter by empty case using display func unknown yet; loop display funcs outside?
    pass

# Search display funcs plausible: heading func depends... just iterate all func pairs but prune: heading for states,
# We'll brute nested loops with pruning using python recursion over tokens choosing actions.
# Approach: iterate init (8), heading_func (256), blank_func (256) = 524k; for each, action choices  (?) huge.
# Instead for each init+display, we can deduce required state equivalence?
# Simpler brute force with backtracking over token actions checking all seq involving that token iteratively.
# Order tokens, assign action, test data cases where all tokens assigned or empty/single/pair.

cases_by_token={t:[] for t in token_list}
for seq,out in data.items():
    for t in seq: cases_by_token[t].append((seq,out))

def simulate(seq, assign, init):
    idx=state_index(init)
    for t in seq:
        idx=assign[t][idx]
    return idx

# Iterate display funcs but only those that are monotonic (?) Let's iterate all and then backtrack; prune with [] case: final state for [] must map to data[()]
solutions=[]
for hi,hf in enumerate(funcs):
 for bi,bf in enumerate(funcs):
    # empty must match
    ok_init=[]
    for init in states:
        idx=state_index(init)
        if (hf[idx],bf[idx])==data[()]:
            ok_init.append(init)
    if not ok_init: continue
    for init in ok_init:
        assign={}
        # backtrack tokens
        def bt(ti):
            if ti==len(token_list):
                # check all
                for seq,out in data.items():
                    idx=simulate(seq,assign,init)
                    if (hf[idx],bf[idx])!=out:
                        return
                solutions.append((init,hi,bi,{k:assign[k] for k in assign}))
                print("SOL",init,hi,bi,assign)
                return
            t=token_list[ti]
            for hg,act in acts[t]:
                assign[t]=act
