import subprocess, os
AG="/workspace/executable"
def run(args, inp=None, cwd="/tmp/agtest", env=None):
    e=os.environ.copy()
    if env: e.update(env)
    try:
        if inp is None:
            p=subprocess.run([AG]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.DEVNULL, cwd=cwd, env=e, timeout=10)
        else:
            p=subprocess.run([AG]+args, input=inp, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=e, timeout=10)
    except subprocess.TimeoutExpired as ex:
        return (ex.stdout or b''), (ex.stderr or b'')+b'<TIMEOUT>', 999
    return p.stdout, p.stderr, p.returncode
def show(args, inp=None, cwd="/tmp/agtest", env=None):
    o,e,rc=run(args,inp,cwd,env)
    print(f"$ ag {' '.join(map(repr,args))} rc={rc}", flush=True)
    print("OUT:", repr(o.decode(errors='backslashreplace')), flush=True)
    if e: print("ERR:", repr(e.decode(errors='backslashreplace')), flush=True)
    print(flush=True)
