class RegexError(Exception):
    def __init__(self, pos, msg):
        Exception.__init__(self, msg)
        self.pos = pos
        self.msg = msg

class CompiledRegex:
    def __init__(self, pattern, ignore_case, multiline_flag):
        self.pattern = pattern
        self.ignore_case = ignore_case
        self.multiline_flag = multiline_flag
        self.pcre_code = None
        self.py_re = None
        if PCRE.available:
            options = 0
            if ignore_case:
                options |= PCRE_CASELESS
            if multiline_flag:
                options |= PCRE_MULTILINE
            errptr = ctypes.c_char_p()
            erroffset = ctypes.c_int(0)
            pat_buf = ctypes.create_string_buffer(pattern, len(pattern)+1 if len(pattern) else 1)
            code = PCRE.lib.pcre_compile(pat_buf, options, ctypes.byref(errptr), ctypes.byref(erroffset), None)
            if not code:
                msg = errptr.value if errptr.value else b"unknown error"
                raise RegexError(int(erroffset.value), msg)
            self.pcre_code = code
        else:
            flags = 0
            if ignore_case:
                flags |= re.IGNORECASE
            if multiline_flag:
                flags |= re.MULTILINE
            try:
                self.py_re = re.compile(pattern, flags)
            except re.error as e:
                raise RegexError(int(getattr(e, 'pos', 0) or 0), (getattr(e, 'msg', str(e)).encode()))
    def search_from(self, subject, start):
        if self.pcre_code is not None:
            if start < 0:
                start = 0
            length = len(subject)
            if length == 0:
                subj = ctypes.create_string_buffer(1)
            else:
                subj = ctypes.create_string_buffer(subject, length)
            ovec_size = 300
            ovec = (ctypes.c_int * ovec_size)()
            rc = PCRE.lib.pcre_exec(self.pcre_code, None, subj, length, start, 0, ovec, ovec_size)
            if rc < 0:
                return None
            return (int(ovec[0]), int(ovec[1]))
        else:
            if start > len(subject):
                return None
            m = self.py_re.search(subject, start)
            if m is None:
                return None
            return (int(m.start()), int(m.end()))
    def find_all(self, subject, max_count=0):
        matches = []
        if subject is None:
            return matches
        length = len(subject)
        offset = 0
        # Match original loop: searches while offset < len (allows a match
        # starting at 0 in an empty subject only through search_from use).
        if length == 0:
            r = self.search_from(subject, 0)
            if r is not None:
                matches.append(r)
            return matches
        while offset < length:
            r = self.search_from(subject, offset)
            if r is None:
                break
            s, e = r
            if s < 0:
                break
            if s < offset:
                # Should not happen; avoid infinite loops.
                s = offset
            matches.append((s, e))
            if max_count and len(matches) >= max_count:
                break
            if e > s:
                offset = e
            else:
                offset = e + 1
        return matches
    def search_any(self, subject):
        if subject is None or len(subject) == 0:
            r = self.search_from(subject, 0) if subject is not None else None
            return r
        return self.search_from(subject, 0)

