# Glob matching, similar to fnmatch but '*'/'?' do not cross '/'
def glob_to_regex(pat):
    out = []
    i = 0
    n = len(pat)
    while i < n:
        c = pat[i:i+1]
        ch = pat[i]
        if c == b'*':
            out.append(b'[^/]*')
            i += 1
        elif c == b'?':
            out.append(b'[^/]')
            i += 1
        elif c == b'[':
            j = i + 1
            if j < n and pat[j:j+1] == b'!':
                j += 1
            if j < n and pat[j:j+1] == b']':
                j += 1
            while j < n and pat[j:j+1] != b']':
                j += 1
            if j >= n:
                out.append(re.escape(c))
                i += 1
            else:
                stuff = pat[i+1:j]
                if stuff.startswith(b'!'):
                    stuff = b'^' + stuff[1:]
                # a '/' inside a class should not match '/'; keep as is
                out.append(b'[' + stuff + b']')
                i = j + 1
        else:
            out.append(re.escape(c))
            i += 1
    return b'^' + b''.join(out) + b'$'

_glob_cache = {}
def glob_match(pattern, string):
    if pattern is None or string is None:
        return False
    key = (pattern, string)
    # caching regex only
    rx = _glob_cache.get(pattern)
    if rx is None:
        try:
            rx = re.compile(glob_to_regex(pattern))
        except Exception:
            rx = False
        _glob_cache[pattern] = rx
    if rx is False:
        return False
    return rx.match(string) is not None

def has_glob_meta(pattern):
    return any(b in pattern for b in (42, 63, 91))  # * ? [

