    # Map aliases to same key
    return (action,)

def parse_args(argv, opts):
    positionals = []
    i = 0
    n = len(argv)
    options_enabled = True
    while i < n:
        arg = argv[i]
        if options_enabled and arg == b'--':
            options_enabled = False
            i += 1
            continue
        if options_enabled and arg.startswith(b'--') and len(arg) > 2:
            body = arg[2:]
            if b'=' in body:
                name, eqval = body.split(b'=', 1)
                has_eq = True
            else:
                name = body
                eqval = None
                has_eq = False
            # exact match first
            matches = [(nm, ak, ac) for (nm, ak, ac) in LONG_OPTIONS if nm == name]
            chosen = None
            if matches:
                chosen = matches[0]
            else:
                pref = [(nm, ak, ac) for (nm, ak, ac) in LONG_OPTIONS if nm.startswith(name) and name != b'']
                if not pref:
                    getopt_error(b"unrecognized option '--" + body + b"'")
                # If all matches are file types, or all same canonical, choose first
                keys = set(canonical_action_for_match(ac) for (nm, ak, ac) in pref)
                if len(keys) == 1:
                    chosen = pref[0]
                else:
                    possibilities = b" ".join(b"'--" + nm + b"'" for (nm, ak, ac) in pref)
                    getopt_error(b"option '--" + body + b"' is ambiguous; possibilities: " + possibilities)
            nm, akind, action = chosen
            if akind == 'none':
                if has_eq:
                    getopt_error(b"option '--" + nm + b"' doesn't allow an argument")
                optarg = None
                apply_action(action, optarg, opts)
                i += 1
            elif akind == 'required':
                if has_eq:
                    optarg = eqval
                    i += 1
                else:
                    if i+1 >= n:
                        getopt_error(b"option '--" + nm + b"' requires an argument")
                    optarg = argv[i+1]
                    i += 2
                apply_action(action, optarg, opts)
            elif akind == 'optional':
                optarg = eqval if has_eq else None
                apply_action(action, optarg, opts)
                i += 1
            else:
                i += 1
            continue
        if options_enabled and arg.startswith(b'-') and len(arg) > 1:
            # short cluster
            cluster = arg[1:]
            j = 0
            consumed_next = False
            while j < len(cluster):
                ch = cluster[j]
                entry = SHORT_OPTIONS.get(ch)
                if entry is None:
                    getopt_error(b"invalid option -- '" + bytes([ch]) + b"'")
                action, akind = entry
                if akind == 'none':
                    apply_action(action, None, opts)
                    j += 1
                    continue
                elif akind == 'required':
                    rest = cluster[j+1:]
                    if rest != b'':
                        # strip leading '=' if present (GNU-style -A=val is
                        # handled only for optional; for required -W=5 the
                        # optarg in getopt is "=5" so keep behaviour simple
                        # by stripping one leading '=')
                        optarg = rest[1:] if rest.startswith(b'=') else rest
                        apply_action(action, optarg, opts)
                        j = len(cluster)
                    else:
                        if i+1 >= n:
                            getopt_error(b"option requires an argument -- '" + bytes([ch]) + b"'")
                        optarg = argv[i+1]
                        consumed_next = True
                        apply_action(action, optarg, opts)
                        j = len(cluster)
                    continue
                elif akind == 'optional':
                    rest = cluster[j+1:]
                    if rest != b'':
                        optarg = rest[1:] if rest.startswith(b'=') else rest
                        apply_action(action, optarg, opts)
                        j = len(cluster)
                    else:
                        # peek next arg if it is an integer
                        if i+1 >= n:
                            getopt_error(b"option requires an argument -- '" + bytes([ch]) + b"'")
                        nxt = argv[i+1]
                        if is_integer_string(nxt):
                            optarg = nxt
                            consumed_next = True
                        else:
                            optarg = None
                        apply_action(action, optarg, opts)
                        j = len(cluster)
                    continue
            i += 2 if consumed_next else 1
            continue
        # positional (including single '-')
        positionals.append(arg)
        i += 1
    return positionals

