# ---------------- Ignore handling ----------------
class IgnoreRule:
    __slots__ = ('pattern','negated','dir_only','is_cli')
    def __init__(self, pattern, negated=False, dir_only=False, is_cli=False):
        self.pattern = pattern
        self.negated = negated
        self.dir_only = dir_only
        self.is_cli = is_cli

class RuleSet:
    __slots__ = ('rules','base_abs','is_global')
    def __init__(self, rules, base_abs, is_global=False):
        self.rules = rules
        self.base_abs = base_abs
        self.is_global = is_global

def parse_ignore_line(line, is_cli=False):
    if line is None:
        return None
    # original trims trailing whitespace (including \r and spaces)
    pat = line.rstrip(b' \t\r\n')
    if not is_cli:
        if pat == b'':
            return None
        if pat.startswith(b'#'):
            return None
    else:
        if pat == b'':
            return None
    negated = False
    if not is_cli:
        if pat.startswith(b'\\#') or pat.startswith(b'\\!'):
            pat = pat[1:]
        elif pat.startswith(b'!'):
            negated = True
            pat = pat[1:]
    dir_only = False
    if pat.endswith(b'/'):
        dir_only = True
        pat = pat.rstrip(b'/')
        if pat == b'':
            return None
    return IgnoreRule(pat, negated, dir_only, is_cli)

def load_ignore_file(path_bytes, is_global=False):
    rules = []
    try:
        with open(path_bytes, 'rb') as f:
            data = f.read()
    except Exception:
        return None
    for line in data.split(b'\n'):
        r = parse_ignore_line(line, is_cli=False)
        if r is not None:
            rules.append(r)
    # base is directory containing file for regular per-dir files;
    # caller overrides base
    return rules

def rule_matches(rule, candidate_abs, base_abs, basename, display_path, internal_path, is_dir, search_root_abs):
    if rule.dir_only and not is_dir:
        return False
    pat = rule.pattern
    if pat == b'':
        return False
    # compute rel to base
    base = base_abs
    if base is None:
        base = search_root_abs
    rel = None
    if base is not None:
        if candidate_abs == base:
            rel = b''
        elif candidate_abs.startswith(base + b'/'):
            rel = candidate_abs[len(base)+1:]
        else:
            # candidate not under base: only basename matching can work
            rel = None
    # 1) basename
    if glob_match(pat, basename):
        return True
    # 2) display / internal full path (covers ./... patterns)
    if display_path and glob_match(pat, display_path):
        return True
    if internal_path and internal_path != display_path and glob_match(pat, internal_path):
        return True
    # 3) rel-path handling
    if rel is not None and rel != b'':
        if pat.startswith(b'/'):
            if glob_match(pat[1:], rel):
                return True
        elif pat.startswith(b'./'):
            stripped = pat[2:]
            if not has_glob_meta(stripped):
                if rel == stripped:
                    return True
                # suffix by components
                parts = rel.split(b'/')
                pat_parts = stripped.split(b'/')
                if len(pat_parts) <= len(parts) and parts[len(parts)-len(pat_parts):] == pat_parts:
                    return True
            else:
                # ./ glob against ./rel
                if glob_match(pat, b'./' + rel):
                    return True
        elif b'/' in pat:
            if not has_glob_meta(pat):
                if rel == pat:
                    return True
                parts = rel.split(b'/')
                pat_parts = pat.split(b'/')
                if len(pat_parts) <= len(parts) and parts[len(parts)-len(pat_parts):] == pat_parts:
                    return True
            else:
                # glob with slash but not ./ : original largely does not
                # match files via rel; directory /* case handled below
                pass
        else:
            # no slash: already basename-checked; also rel == pat for dirs
            if rel == pat:
                return True
    # 4) directory special: pattern ending in /* matching dirname/
    if is_dir:
        if glob_match(pat, basename + b'/'):
            return True
        if display_path and glob_match(pat, display_path + b'/'):
            return True
    return False

def candidate_is_ignored(candidate_abs, basename, display_path, internal_path, is_dir, active_rulesets, search_root_abs):
    cli_positive = False
    file_positive = False
    file_negated = False
    for rs in active_rulesets:
        base = rs.base_abs
        for rule in rs.rules:
            if rule.dir_only and not is_dir:
                continue
            matched = rule_matches(rule, candidate_abs, base, basename, display_path, internal_path, is_dir, search_root_abs)
            if matched:
                if rule.is_cli:
                    cli_positive = True
                else:
                    if rule.negated:
                        file_negated = True
                    else:
                        file_positive = True
    if is_dir:
        # directory negation does not resurrect a pruned directory in ag
        return cli_positive or file_positive
    if cli_positive:
        return True
    if file_negated:
        return False
    return file_positive

def load_dir_rules(dir_fs_path, opts):
    """Load ignore files for a directory. Returns RuleSet or None."""
    if opts.all_types or opts.all_text or opts.unrestricted:
        return None
    rules = []
    # order: .ignore, .gitignore, .git/info/exclude, .hgignore
    names = []
    names.append(b'.ignore')
    if not opts.skip_vcs_ignores:
        names.append(b'.gitignore')
    if not opts.skip_vcs_ignores:
        names.append(b'.git/info/exclude')
    if not opts.skip_vcs_ignores:
        names.append(b'.hgignore')
    for nm in names:
        p = dir_fs_path + b'/' + nm if not dir_fs_path.endswith(b'/') else dir_fs_path + nm
        r = load_ignore_file(p)
        if r:
            rules.extend(r)
    if not rules:
        return None
    base_abs = os.path.abspath(dir_fs_path)
    return RuleSet(rules, base_abs, False)

def determine_global_rules(opts):
    rulesets = []
    if opts.all_types or opts.all_text or opts.unrestricted:
        return rulesets
    home = None
    if b'HOME' in os.environb:
        home = os.environb[b'HOME']
    else:
        try:
            home = os.fsencode(os.path.expanduser('~'))
        except Exception:
            home = b''
    # HOME/.agignore
    if home is not None:
        p = home + b'/.agignore'
        r = load_ignore_file(p)
        if r:
            rulesets.append(RuleSet(r, None, True))
        if not opts.skip_vcs_ignores:
            # global git excludes
            excludes = None
            gitconfig = home + b'/.gitconfig'
            try:
                with open(gitconfig, 'rb') as f:
                    cfg = f.read()
                in_core = False
                for rawline in cfg.split(b'\n'):
                    line = rawline.strip()
                    if line.startswith(b'['):
                        in_core = line.lower().startswith(b'[core]')
                        continue
                    if in_core and b'=' in line:
                        k, v = line.split(b'=', 1)
                        if k.strip().lower() == b'excludesfile':
                            excludes = v.strip().strip(b'"')
                            break
            except Exception:
                excludes = None
            if excludes:
                if excludes.startswith(b'~/'):
                    excludes = home + excludes[1:]
                elif excludes == b'~':
                    excludes = home
                expath = excludes
            else:
                expath = home + b'/.config/git/ignore'
            r2 = load_ignore_file(expath)
            if r2:
                rulesets.append(RuleSet(r2, None, True))
    # CLI ignores (positive only)
    if opts.ignore_patterns:
        cli_rules = []
        for pat in opts.ignore_patterns:
            r = parse_ignore_line(pat, is_cli=True)
            if r is not None:
                cli_rules.append(r)
        if cli_rules:
            rulesets.append(RuleSet(cli_rules, None, True))
    # -p files
    for pth in opts.path_to_ignore:
        r = load_ignore_file(pth)
        if r:
            rulesets.append(RuleSet(r, None, True))
    return rulesets

