# ---------------- Search core ----------------
def build_query_regex():
    pat = OPTS.pattern_bytes
    if OPTS.literal:
        src = re.escape(pat)
    else:
        src = pat
    if OPTS.word_regexp:
        src = rb'\b(?:' + src + rb')\b'
    ci = effective_ignore_case(OPTS.pattern_original_for_case)
    ml = OPTS.multiline
    return compile_regex(src, ci, multiline_flag=ml)

def build_file_regex(pat):
    # -G / -g pattern, regex (not literal/word, even if -Q/-w set,
    # matching ag's observable behaviour for plain patterns)
    ci = effective_ignore_case(pat)
    return compile_regex(pat, ci, multiline_flag=True)

def split_lines(content):
    if content == b'':
        return [], [], False
    parts = content.split(b'\n')
    if content.endswith(b'\n'):
        real = parts[:-1]
        has_phantom = True
    else:
        real = parts
        has_phantom = False
    starts = []
    off = 0
    for ln in real:
        starts.append(off)
        off += len(ln) + 1
    return real, starts, has_phantom

def line_index_for_offset(starts, real_lines, offset):
    # index of real line containing offset (offset at a '\n' belongs to
    # that line). offset==len at EOF maps to last real line.
    if not real_lines:
        return 0
    # binary search manually
    lo = 0
    hi = len(real_lines)-1
    idx = 0
    for i, st in enumerate(starts):
        line_end = st + len(real_lines[i])  # index of '\n' or len
        if offset <= line_end:
            idx = i
            break
        idx = i
    else:
        idx = len(real_lines)-1
    return idx

def matches_line_info(content, matches):
    real, starts, has_phantom = split_lines(content)
    matched = set()
    per_line_intervals = {}
    per_line_col = {}
    for (s, e) in matches:
        if not real and not has_phantom:
            continue
        if s == e:
            if s >= len(content):
                if real:
                    first = len(real)-1
                else:
                    first = 0
                last = first
            else:
                first = line_index_for_offset(starts, real, s)
                last = first
            idxs = [first]
        else:
            first = line_index_for_offset(starts, real, s)
            last_off = e-1
            last = line_index_for_offset(starts, real, last_off)
            if last_off >= 0 and last_off < len(content) and content[last_off:last_off+1] == b'\n':
                last = last + 1  # may be phantom index
            idxs = list(range(first, last+1))
        for idx in idxs:
            matched.add(idx)
            if idx < len(real):
                ls = starts[idx]
                le = ls + len(real[idx])
                inter_s = max(s, ls)
                inter_e = min(e, le)
                if inter_s < inter_e or (s == e and ls <= s <= le):
                    per_line_intervals.setdefault(idx, []).append((inter_s-ls, inter_e-ls, e > le))
                if idx not in per_line_col:
                    if s >= ls and s <= le:
                        per_line_col[idx] = (s - ls + 1)
                    elif s < ls:
                        per_line_col[idx] = 0
                    else:
                        per_line_col[idx] = 0
    return real, starts, has_phantom, matched, per_line_intervals, per_line_col

def find_matches_in_content(compiled, content):
    if OPTS.multiline:
        return compiled.find_all(content, max_count=OPTS.max_count if OPTS.max_count > 0 else 0)
    else:
        # per-line search
        real, starts, has_phantom = split_lines(content)
        result = []
        for idx, ln in enumerate(real):
            sub = compiled.find_all(ln, max_count=0)
            for (s, e) in sub:
                result.append((starts[idx]+s, starts[idx]+e))
                if OPTS.max_count > 0 and len(result) >= OPTS.max_count:
                    return result
        return result

def is_binary_content(content):
    chunk = content[:512]
    return b'\x00' in chunk

def try_decompress_zip(content):
    # gz magic
    if content[:2] == b'\x1f\x8b':
        try:
            return gzip.decompress(content)
        except Exception:
            return None
    # xz magic
    if content[:6] == b'\xfd7zXZ\x00':
        try:
            return lzma.decompress(content, format=lzma.FORMAT_XZ)
        except Exception:
            try:
                return lzma.decompress(content)
            except Exception:
                return None
    return None

