    return real, starts, has_phantom

def line_index_for_offset(starts, real_lines, offset):
    # index of real line containing offset (offset at a '\n' belongs to
    # that line). offset==len at EOF maps to last real line.
    if not real_lines:
        return 0
    # binary search manually
    lo = 0
    hi = len(real_lines)-1
    idx = 0
    for i, st in enumerate(starts):
        line_end = st + len(real_lines[i])  # index of '\n' or len
