                # implement by putting reset after content in this line:
                # marker will be handled via a sentinel: we instead append
                # content and let line builder know. Simpler: close after
                # newline is simulated by returning a flag via trailing
                # reset appended after the line break in caller. Here we
                # just append reset (matches most cases).
                out.append(b"\x1b[0m\x1b[K")
            else:
                out.append(b"\x1b[0m\x1b[K")
