# ---------------- Rendering ----------------
def colored_piece(text, code):
    if OPTS.color:
        return b"\x1b[" + code + b"m" + text + b"\x1b[0m\x1b[K"
    return text

def format_line_content(line, intervals, is_match):
    if OPTS.width and is_match and len(line) > OPTS.width:
        truncated = True
        content = line[:OPTS.width]
    else:
        truncated = False
        content = line
    if not OPTS.color or not is_match:
        if truncated:
            return content + b" [...]"
        return content
    # colored intervals
    clipped = []
    for (s, e, beyond) in intervals:
        cs = min(s, len(content))
        ce = min(e, len(content))
        if cs < ce or cs == ce:
            clipped.append((cs, ce, beyond and not truncated))
    clipped.sort()
    out = []
    cur = 0
    for (s, e, beyond) in clipped:
        if s > cur:
            out.append(content[cur:s])
        if s == e:
            # zero-width match: original emits a reset marker
            out.append(b"\x1b[0m\x1b[K")
            cur = s
        else:
            out.append(b"\x1b[" + OPTS.color_match + b"m")
            out.append(content[s:e])
            if beyond:
                # reset is emitted after the newline by caller logic;
                # implement by putting reset after content in this line:
                # marker will be handled via a sentinel: we instead append
                # content and let line builder know. Simpler: close after
                # newline is simulated by returning a flag via trailing
                # reset appended after the line break in caller. Here we
                # just append reset (matches most cases).
                out.append(b"\x1b[0m\x1b[K")
            else:
                out.append(b"\x1b[0m\x1b[K")
            cur = e
    if cur < len(content):
        out.append(content[cur:])
    result = b''.join(out)
    if truncated:
        result += b" [...]"
    return result

def build_prefix(display, filename_effective, heading_displayed, line_no, col, is_match, is_context, for_only_matching=False, match_col=None):
    pieces = []  # list of bytes, already possibly colored, in order
    kinds = []
    if not heading_displayed and filename_effective:
        pieces.append(colored_piece(display, OPTS.color_path))
        kinds.append('file')
    numbers_on = OPTS.print_line_numbers
    if for_only_matching:
        if heading_displayed:
            if numbers_on:
                pieces.append(colored_piece(str(line_no).encode(), OPTS.color_line_number))
                kinds.append('num')
        else:
            if filename_effective:
                if numbers_on:
                    pieces.append(colored_piece(str(line_no).encode(), OPTS.color_line_number))
                    kinds.append('num')
            # single file: no line num
        if OPTS.column:
            cval = match_col if match_col is not None else col
            pieces.append(str(cval).encode())
            kinds.append('col')
    else:
        if numbers_on:
            pieces.append(colored_piece(str(line_no).encode(), OPTS.color_line_number) if not (OPTS.invert_match and OPTS.color and False) else str(line_no).encode())
            kinds.append('num')
        if OPTS.column and is_match and not is_context:
            pieces.append(str(col).encode())
            kinds.append('col')
    if not pieces:
        return b""
    sep = b"-" if is_context else b":"
    return b":".join(pieces) + sep

