    prev_idx = None
    for idx in sorted(selected):
        is_match = idx in matched_set
        if context_enabled and prev_idx is not None and idx > prev_idx + 1 and (OPTS.before or OPTS.after):
            # separator only when context was requested (values non-zero,
            # including clamped negatives via flag)
