# ---------------- File processing ----------------
def process_file(fs_path, internal_path, display_path, filename_effective, is_direct=False, is_g_direct=False):
    global ANY_FOUND
    # -g direct file quirk: print every line
    try:
        with open(fs_path, 'rb') as f:
            content = f.read()
    except OSError as e:
        log_err(b"ERR: Skipping " + internal_path + b": Error opening file: " + os.strerror(e.errno).encode() + b"\n")
        return False
    except Exception as e:
        log_err(b"ERR: Skipping " + internal_path + b": Error opening file: " + str(e).encode() + b"\n")
        return False
    if len(content) == 0:
        return False
    if is_g_direct:
        real, starts, has_phantom = split_lines(content)
        matched_set = set(range(len(real)))
        if has_phantom:
            matched_set.add(len(real))
        intervals = {}
        for idx in range(len(real)):
            intervals[idx] = [(0, len(real[idx]), False)]
        ctx = FileCtx(display_path, internal_path, filename_effective)
        # synthesize a spanning match for colour
        raw = [(0, len(content))]
        per_line_col = {idx: 1 for idx in range(len(real))}
        block = render_block(ctx, content, raw, matched_set, intervals, per_line_col, real, starts, has_phantom)
        if block:
            emit_block(block, use_break=True)
            return True
        return False
    searched_content = content
    is_zip = False
    if OPTS.search_zip:
        dec = try_decompress_zip(content)
        if dec is not None:
            searched_content = dec
            is_zip = True
            if len(searched_content) == 0:
                return False
    binary = is_binary_content(searched_content) if not is_zip else is_binary_content(searched_content)
    # For zip content, binary check is on decompressed data (it will be
    # treated as text usually); if decompressed is binary, fall through
    # to binary logic below.
    if binary and not is_zip:
        if not (OPTS.search_binary or OPTS.all_types):
            return False
        # binary searched
        STATS.files_searched += 1
        STATS.bytes_searched += len(searched_content)
        raw_matches = find_matches_in_content(OPTS.compiled_query, searched_content)
        capped_count = len(raw_matches)
        has = capped_count > 0
        if has:
            STATS.matches += capped_count
            STATS.files_contained += 1
        if OPTS.max_count > 0 and capped_count >= OPTS.max_count:
            log_err(b"ERR: Too many matches in " + internal_path + b". Skipping the rest of this file.\n")
        # modes
        if OPTS.files_without_matches:
            if not has:
                _print_filename_line(display_path)
                return True
            return False
        if OPTS.stats_only:
            if OPTS.print_count:
                if has:
                    _print_count_line(display_path, capped_count, filename_effective)
                return has
            if OPTS.files_with_matches:
                if has:
                    _print_filename_line(display_path)
                return has
            return has
        if OPTS.print_count:
            if has:
                _print_count_line(display_path, capped_count, filename_effective)
            return has
        if OPTS.files_with_matches:
            if has:
                _print_filename_line(display_path)
            return has
        if has:
            block = b"Binary file " + display_path + b" matches.\n"
            emit_block(block, use_break=True)
            return True
        return False
    if binary and is_zip:
        # decompressed binary: treat like binary above (rare)
        if not (OPTS.search_binary or OPTS.all_types):
            return False
    # text file
    STATS.files_searched += 1
    STATS.bytes_searched += len(searched_content)
    raw_matches = find_matches_in_content(OPTS.compiled_query, searched_content)
    real, starts, has_phantom, matched_set, per_line_intervals, per_line_col = matches_line_info(searched_content, raw_matches)
    if OPTS.invert_match:
        matched_real = set(i for i in matched_set if i < len(real))
        inverted = [i for i in range(len(real)) if i not in matched_real]
        # groups
        groups = 0
        prev = -10
        for idx in inverted:
            if idx != prev + 1:
                groups += 1
            prev = idx
        count_val = groups
        has = len(inverted) > 0
        # per line intervals for inverted: whole line
        inv_intervals = {}
        inv_col = {}
        prev_idx = -10
        grp_start = True
        for idx in inverted:
            inv_intervals[idx] = [(0, len(real[idx]), False)]
            if idx != prev_idx + 1:
                inv_col[idx] = 1
            else:
                inv_col[idx] = 0
            prev_idx = idx
        render_matched = set(inverted)
        render_intervals = inv_intervals
        render_col = inv_col
    else:
        count_val = len(raw_matches)
        has = count_val > 0
        render_matched = matched_set
        render_intervals = per_line_intervals
        render_col = per_line_col
    if has:
        STATS.matches += count_val
        STATS.files_contained += 1
    if OPTS.max_count > 0 and len(raw_matches) >= OPTS.max_count and not OPTS.invert_match:
        # In inverted mode the original also logs in some cases; limit to
        # normal mode for predictability except when raw count reached.
        log_err(b"ERR: Too many matches in " + internal_path + b". Skipping the rest of this file.\n")
    elif OPTS.max_count > 0 and OPTS.invert_match and len(raw_matches) >= OPTS.max_count:
        log_err(b"ERR: Too many matches in " + internal_path + b". Skipping the rest of this file.\n")
    # mode dispatch
    if OPTS.files_without_matches:
        # based on raw match existence (not inverted)
        if len(raw_matches) == 0:
            _print_filename_line(display_path)
            return True
        return False
    if OPTS.stats_only:
        if OPTS.print_count:
            if has:
                # in stats-only, count is bare (no filename) for directory
                # searches; single file is same anyway
                term = b'\x00' if OPTS.print0 else b'\n'
                WRITER.write(colored_piece(str(count_val).encode(), OPTS.color_line_number) + term if OPTS.color else str(count_val).encode() + term)
            return has
        if OPTS.files_with_matches:
            if has:
                _print_filename_line(display_path)
            return has
        return has
    if OPTS.print_count:
        if has or OPTS.print_all_files:
            _print_count_line(display_path, count_val, filename_effective)
            return True
        return has
    if OPTS.files_with_matches:
        if has or OPTS.print_all_files:
            _print_filename_line(display_path)
            return True
        return has
    # normal content modes
    ctx = FileCtx(display_path, internal_path, filename_effective)
    if not has:
        if OPTS.print_all_files:
            # heading-only block (possibly empty)
            if heading_on() and (filename_effective or getattr(OPTS, 'heading_explicit', False)) and OPTS.print_filename_flag:
                term = b'\x00' if OPTS.print0 else b'\n'
                block = colored_piece(display_path, OPTS.color_path) + term
            else:
                block = b""
            emit_block(block, use_break=True)
            return True
        return False
    block = render_block(ctx, searched_content, raw_matches, render_matched, render_intervals, render_col, real, starts, has_phantom)
    if block:
        emit_block(block, use_break=True)
        return True
    # a match could produce an empty block for phantom-only cases; still
    # counts as found
    return has

def _print_filename_line(display):
    term = b'\x00' if OPTS.print0 else b'\n'
    if OPTS.color:
        WRITER.write(colored_piece(display, OPTS.color_path) + term)
    else:
        WRITER.write(display + term)

def _print_count_line(display, count_val, filename_effective):
    term = b'\x00' if OPTS.print0 else b'\n'
    show_name = filename_effective or heading_on()
    if getattr(OPTS, '_single_file_search', False):
        show_name = heading_on()
    if OPTS.color:
        if show_name:
            WRITER.write(colored_piece(display, OPTS.color_path) + b":" + colored_piece(str(count_val).encode(), OPTS.color_line_number) + term)
        else:
            WRITER.write(colored_piece(str(count_val).encode(), OPTS.color_line_number) + term)
    else:
        if show_name:
            WRITER.write(display + b":" + str(count_val).encode() + term)
        else:
            WRITER.write(str(count_val).encode() + term)

