# ---------------- Traversal ----------------
def normalize_display_path(p):
    # Mirror ag's stripping of a single leading ./ and a single trailing /
    disp = p
    if disp.startswith(b'./'):
        disp = disp[2:]
        if disp == b'':
            disp = b''
    if len(disp) > 1 and disp.endswith(b'/'):
        disp = disp[:-1]
    return disp

def join_display(dir_disp, name):
    if dir_disp == b'':
        return name
    if dir_disp.endswith(b'/'):
        return dir_disp + name
    return dir_disp + b'/' + name

def join_internal(dir_internal, name):
    if dir_internal == b'':
        return name
    if dir_internal.endswith(b'/'):
        return dir_internal + name
    return dir_internal + b'/' + name

def is_hidden_name(name):
    return name.startswith(b'.') and name not in (b'.', b'..')

def traverse_directory(dir_fs, dir_internal, dir_display, active_rulesets, search_root_abs, root_device, depth, ancestor_ids, ackmate_filter_inside):
    global ANY_FOUND
    # load this dir's ignore rules
    own_rules = load_dir_rules(dir_fs, OPTS)
    rulesets = list(active_rulesets)
    if own_rules is not None:
        rulesets.append(own_rules)
    try:
        it = os.scandir(dir_fs)
        entries = list(it)
        try:
            it.close()
        except Exception:
            pass
    except OSError as e:
        log_err(b"ERR: Error opening directory " + dir_internal + b": " + os.strerror(e.errno).encode() + b"\n")
        return
    for entry in entries:
        try:
            name = entry.name
            if isinstance(name, str):
                name = os.fsencode(name)
        except Exception:
            continue
        if name in (b'.', b'..'):
            continue
        internal = join_internal(dir_internal, name)
        display = join_display(dir_display, name)
        candidate_abs = os.path.abspath(internal)
        # Determine entry kind without following symlinks first
        try:
            is_link = entry.is_symlink()
        except Exception:
            is_link = False
        try:
            is_dir_nf = entry.is_dir(follow_symlinks=False)
            is_file_nf = entry.is_file(follow_symlinks=False)
        except Exception:
            is_dir_nf = False
            is_file_nf = False
        # hidden check applies to name for non-followed entries as well
        # (symlinks are skipped entirely without -f anyway)
        if is_link:
            if not OPTS.follow:
                continue
            # follow: stat target
            try:
                st = os.stat(internal)
            except OSError:
                log_err(b"ERR: Skipping " + internal + b": Error fstat()ing file.\n")
                continue
            if stat.S_ISDIR(st.st_mode):
                # directory loop detection
                ident = (st.st_dev, st.st_ino)
                if ident in ancestor_ids:
                    log_err(b"ERR: Recursive directory loop: " + internal + b"\n")
                    continue
                if is_hidden_name(name) and not OPTS.hidden and not OPTS.unrestricted:
                    continue
                if candidate_is_ignored(candidate_abs, name, display, internal, True, rulesets, search_root_abs):
                    continue
                if not OPTS.recurse:
                    continue
                if OPTS.depth != -1 and OPTS.depth < 0:
                    maxd = 0
                else:
                    maxd = OPTS.depth
                if maxd != -1 and depth >= maxd:
                    continue
                if OPTS.one_device and root_device is not None and st.st_dev != root_device:
                    continue
                # ackmate filter for dirs
                child_filter_inside = ackmate_filter_inside
                if OPTS.ackmate_dir_filter is not None and not child_filter_inside:
                    if OPTS._ackmate_regex.search_any(name) or OPTS._ackmate_regex.search_any(display) or OPTS._ackmate_regex.search_any(internal):
                        child_filter_inside = True
                    else:
                        # still must descend in case a subdir matches?
                        # original allows deeper dirs to match, so do not prune solely
                        pass
                ancestor_ids.add(ident)
                traverse_directory(internal, internal, display, rulesets, search_root_abs, root_device, depth+1, ancestor_ids, child_filter_inside)
                ancestor_ids.discard(ident)
                continue
            elif stat.S_ISREG(st.st_mode):
                if is_hidden_name(name) and not OPTS.hidden and not OPTS.unrestricted:
                    continue
                if candidate_is_ignored(candidate_abs, name, display, internal, False, rulesets, search_root_abs):
                    continue
                handle_dir_file(internal, internal, display, rulesets, search_root_abs, ackmate_filter_inside, name)
                continue
            else:
                continue
        if is_dir_nf:
            if is_hidden_name(name) and not OPTS.hidden and not OPTS.unrestricted:
                continue
            if candidate_is_ignored(candidate_abs, name, display, internal, True, rulesets, search_root_abs):
                continue
            if not OPTS.recurse:
                continue
            if OPTS.depth != -1 and OPTS.depth < 0:
                maxd = 0
            else:
                maxd = OPTS.depth
            if maxd != -1 and depth >= maxd:
                continue
            # one device
            if OPTS.one_device and root_device is not None:
                try:
                    dst = os.stat(internal)
                    if dst.st_dev != root_device:
                        continue
                except Exception:
                    pass
            ident = None
            try:
                dst = entry.stat(follow_symlinks=False)
                ident = (dst.st_dev, dst.st_ino)
            except Exception:
                ident = None
            child_filter_inside = ackmate_filter_inside
            if OPTS.ackmate_dir_filter is not None and not child_filter_inside:
                try:
                    if OPTS._ackmate_regex.search_any(name) or OPTS._ackmate_regex.search_any(display):
                        child_filter_inside = True
                except Exception:
                    pass
            if ident is not None:
                ancestor_ids.add(ident)
            traverse_directory(internal, internal, display, rulesets, search_root_abs, root_device, depth+1, ancestor_ids, child_filter_inside)
            if ident is not None:
                ancestor_ids.discard(ident)
            continue
        if is_file_nf:
            if is_hidden_name(name) and not OPTS.hidden and not OPTS.unrestricted:
                continue
            if candidate_is_ignored(candidate_abs, name, display, internal, False, rulesets, search_root_abs):
                continue
            handle_dir_file(internal, internal, display, rulesets, search_root_abs, ackmate_filter_inside, name)
            continue
        # other kinds: skip silently
        continue

def handle_dir_file(fs_path, internal, display, rulesets, search_root_abs, ackmate_filter_inside, basename):
    global ANY_FOUND
    filename_effective = True
    if not OPTS.print_filename_flag:
        filename_effective = False
    # -g filename-pattern mode
    if OPTS.filename_pattern is not None:
        matched = False
        if OPTS.file_types:
            matched = True
        else:
            try:
                matched = OPTS._file_regex.search_any(internal) is not None
            except Exception:
                matched = False
        if matched:
            term = b'\x00' if OPTS.print0 else b'\n'
            if OPTS.color:
                WRITER.write(colored_piece(display, OPTS.color_path) + term)
            else:
                WRITER.write(display + term)
            ANY_FOUND = True
        return
    # -G filter
    if OPTS.file_types:
        ok = False
        for tname in OPTS.file_types:
            for (tn, exts) in FILE_TYPES:
                if tn == tname:
                    for ext in exts:
                        if basename.endswith(b'.' + ext.encode()):
                            ok = True
        if not ok:
            return
    elif OPTS.file_search_regex is not None:
        try:
            if OPTS._file_regex.search_any(internal) is None:
                return
        except Exception:
            return
    # ackmate dir filter
    if OPTS.ackmate_dir_filter is not None and not ackmate_filter_inside:
        try:
            if OPTS._ackmate_regex.search_any(basename) is None and OPTS._ackmate_regex.search_any(display) is None:
                return
        except Exception:
            pass
    found = process_file(fs_path, internal, display, filename_effective, is_direct=False)
    if found:
        ANY_FOUND = True

def process_top_path(path_arg, global_rulesets):
    global ANY_FOUND
    # fs path is raw arg; but strip a single trailing slash for stat when
    # it is not root (ag does this for a.txt/ case via OS handling anyway)
    try:
        st = os.stat(path_arg)
    except OSError as e:
        en = e.errno
        log_err(b"ERR: Error stat()ing: " + path_arg + b"\n")
        msg = os.strerror(en).encode() if en else b"No such file or directory"
        log_err(b"ERR: Error opening directory " + path_arg + b": " + msg + b"\n")
        return
    disp = normalize_display_path(path_arg)
    if stat.S_ISDIR(st.st_mode):
        root_abs = os.path.abspath(path_arg)
        root_device = st.st_dev if OPTS.one_device else st.st_dev
        # ancestor set
        ancestor = set()
        ancestor.add((st.st_dev, st.st_ino))
        # dir_display: for '.' case disp == '' (since '.'?? normalize gives '.')
        # Our normalize: '.' -> '.' (len 1, no strip); need special-case:
        if path_arg in (b'.', b'./'):
            dir_display = b''
        elif path_arg == b'/':
            dir_display = b'/'
