# ---------------- Stream ----------------
def process_stream(data):
    global ANY_FOUND
    # split into lines (a trailing \n does not create an extra line)
    if data == b'':
        lines = []
    else:
        parts = data.split(b'\n')
        if data.endswith(b'\n'):
            lines = parts[:-1]
        else:
            lines = parts
    any_match = False
    # maintain context state using simple set selection like a file
    matches_per_line = []
    matched_idx = set()
    for idx, ln in enumerate(lines):
        ms = OPTS.compiled_query.find_all(ln, max_count=OPTS.max_count if OPTS.max_count > 0 else 0)
        matches_per_line.append(ms)
        if ms:
            matched_idx.add(idx)
    if OPTS.invert_match:
        inverted_idx = set(i for i in range(len(lines)) if i not in matched_idx)
        effective_matched = inverted_idx
    else:
        effective_matched = matched_idx
    # stats per line
    for idx, ln in enumerate(lines):
        STATS.files_searched += 1
        # bytes: line plus newline if present originally (except maybe last)
        has_nl = not (idx == len(lines)-1 and not data.endswith(b'\n'))
        STATS.bytes_searched += len(ln) + (1 if has_nl and data != b'' else 0)
        ms = matches_per_line[idx]
        if OPTS.invert_match:
            if idx in effective_matched:
                STATS.matches += 1
                STATS.files_contained += 1
        else:
            if ms:
                STATS.matches += len(ms)
                STATS.files_contained += 1
    has_any_effective = len(effective_matched) > 0
    # modes
    if OPTS.files_without_matches:
        return False
    if OPTS.files_with_matches:
        return has_any_effective
    # selected lines for context / passthrough
    selected = set(effective_matched)
    if getattr(OPTS, 'passthrough', False):
        selected = set(range(len(lines)))
    else:
        if OPTS.before or OPTS.after:
            before = OPTS.before if OPTS.before > 0 else 0
            after = OPTS.after if OPTS.after > 0 else 0
            exp = set(selected)
            for idx in list(selected):
                for k in range(idx-before, idx+after+1):
                    if 0 <= k < len(lines):
                        exp.add(k)
            selected = exp
    if OPTS.print_count and not OPTS.stats_only:
        # one count per matching line
        for idx in sorted(effective_matched):
            cnt = 1 if OPTS.invert_match else len(matches_per_line[idx])
            term = b'\x00' if OPTS.print0 else b'\n'
            WRITER.write(str(cnt).encode() + term)
        return has_any_effective
    if OPTS.stats_only:
        if OPTS.print_count:
            for idx in sorted(effective_matched):
                cnt = 1 if OPTS.invert_match else len(matches_per_line[idx])
                term = b'\x00' if OPTS.print0 else b'\n'
                WRITER.write(str(cnt).encode() + term)
        return has_any_effective
    # normal output line by line
    for idx in sorted(selected):
        ln = lines[idx]
        is_match_line = idx in effective_matched
        # context vs match distinction for prefix separator
        is_context = not is_match_line
        ms = matches_per_line[idx]
        if OPTS.passthrough and not is_match_line:
            # print plain (with number if requested and line is matched? passthrough prints all plain)
            # original prints matched lines with formatting, others plain
            WRITER.write(ln + b"\n")
            continue
