        # build a FileCtx-like prefix using stream rules (no filename)
        pieces = []
        if OPTS.print_line_numbers:
            pieces.append(colored_piece(str(idx+1).encode(), OPTS.color_line_number))
        if OPTS.column and is_match_line:
            col = ms[0][0]+1 if ms and not OPTS.invert_match else 1
            pieces.append(str(col).encode())
        prefix = b""
        if pieces:
            prefix = b":".join(pieces) + (b"-" if is_context and (OPTS.before or OPTS.after) else b":")
        body = ln
        if OPTS.color and is_match_line and not OPTS.invert_match:
            intervals = [(s, e, False) for (s, e) in ms]
            body = format_line_content(ln, intervals, True)
        elif OPTS.width and is_match_line and len(ln) > OPTS.width:
            body = ln[:OPTS.width] + b" [...]"
        # for -o with invert, body is whole line (already)
        if OPTS.only_matching and OPTS.invert_match:
            body = ln
        WRITER.write(prefix + body + b"\n")
        if OPTS.max_count > 0 and ms and len(ms) >= OPTS.max_count:
            log_err(b"ERR: Too many matches in . Skipping the rest of this file.\n")
