def main(argv_bytes):
    global OPTS, ANY_FOUND
    opts = Options()
    OPTS = opts
    argv = argv_bytes[1:]
    if len(argv) == 0:
        print_usage()
        return 1
    # preliminary tty facts (used during parsing for group gate defaults)
    try:
        stdout_is_tty = sys.stdout.isatty()
    except Exception:
        stdout_is_tty = False
    opts.color = bool(stdout_is_tty)
    opts.group_gate = bool(stdout_is_tty)
    # workers default (unused except debug)
    try:
        cpus = os.cpu_count() or 1
    except Exception:
        cpus = 1
    opts.workers = min(cpus, 8) if cpus else 1
    try:
        positionals = parse_args(argv, opts)
    except ParseExit as e:
        return e.code
    if opts.help:
        print_usage()
        return 0
    if opts.version:
        out_stdout(VERSION_TEXT)
        return 0
    if opts.list_file_types:
        out_stdout(FILE_TYPES_TEXT)
        return 0
    # unrestricted implies all+hidden+binary
    if opts.unrestricted:
        opts.all_types = True
        opts.hidden = True
    # stdin stream detection
    try:
        stmode = os.fstat(0).st_mode
        stdin_is_stream = stat_module_is_stream(stmode)
