        stdin_is_stream = False
    # heading explicit tracking: parse already set dynamic attr if heading seen
    # Determine pattern / paths
    is_g_mode = opts.filename_pattern is not None
    pattern = None
    paths = []
    explicit_paths = False
    if is_g_mode:
        paths = positionals
        explicit_paths = len(paths) > 0
        if not paths:
            paths = [b'.']
        # dummy pattern for internal use (never searched in dir mode)
        opts.pattern_bytes = opts.filename_pattern
        opts.pattern_original_for_case = opts.filename_pattern
    else:
        if len(positionals) == 0:
            if opts.files_with_matches:
                pattern = b''
                paths = [b'.']
            else:
                log_err(b"ERR: What do you want to search for?\n")
                return 1
        else:
            pattern = positionals[0]
            if len(positionals) > 1:
                paths = positionals[1:]
                explicit_paths = True
            else:
                paths = []
            if pattern == b'' and not opts.files_with_matches:
                log_err(b"ERR: Error: No query. What do you want to search for?\n")
                return 1
        opts.pattern_bytes = pattern if pattern is not None else b''
        opts.pattern_original_for_case = opts.pattern_bytes
        # literal preparation deferred in build_query_regex
    # Compile file regex first (ag reports its errors first)
    opts._file_regex = None
    file_pat = None
    if opts.file_search_regex is not None:
        file_pat = opts.file_search_regex
    elif opts.filename_pattern is not None:
        file_pat = opts.filename_pattern
    if file_pat is not None:
        try:
            opts._file_regex = build_file_regex(file_pat)
        except RegexError as e:
            return bad_regex_exit(e)
    # ackmate dir filter regex (treated like a file regex)
    opts._ackmate_regex = None
    if opts.ackmate_dir_filter is not None:
        try:
            opts._ackmate_regex = compile_regex(opts.ackmate_dir_filter, effective_ignore_case(opts.ackmate_dir_filter), True)
        except RegexError as e:
            return bad_regex_exit(e)
    # Build query regex (unless -g mode where content search uses a dummy;
    # still compile the filename pattern path above, and for direct files
    # the empty-search quirk does not need a real query)
    opts.compiled_query = None
    if not is_g_mode:
        try:
            # For literal mode re.escape handles it; for -l empty pattern
            # compile empty regex.
            opts.compiled_query = build_query_regex()
        except RegexError as e:
            return bad_regex_exit(e)
    else:
        # compile a harmless empty-ish regex for completeness
        try:
            opts.compiled_query = compile_regex(b'', False, True)
        except Exception:
            opts.compiled_query = None
    # stream decision
    force_file_search = opts.parallel or opts.vimgrep or opts.ackmate or is_g_mode
    use_stream = stdin_is_stream and not explicit_paths and not force_file_search
    # line numbers default
    if opts.print_line_numbers is None:
        if stdin_is_stream and not opts.parallel:
            opts.print_line_numbers = False
        else:
            opts.print_line_numbers = True
    setattr(opts, '_num_paths', len(paths) if explicit_paths or is_g_mode else 1)
    if is_g_mode:
        setattr(opts, '_num_paths', len(paths))
    # debug banner (approximation; original prints much more)
    if opts.debug:
        home_val = os.environb.get(b'HOME', b'') if hasattr(os, 'environb') else b''
        out_stdout(b"DEBUG: Found user's home dir: " + home_val + b"\n")
        out_stdout(b"DEBUG: Query is " + (opts.pattern_bytes or b'') + b"\n")
        out_stdout(b"DEBUG: PCRE Version: " + PCRE.version() + b"\n")
    # pager setup
    if opts.pager is not None:
        WRITER.start_pager(opts.pager)
    try:
        if use_stream:
            data = sys.stdin.buffer.read()
            found = process_stream(data)
            ANY_FOUND = bool(found)
        else:
            if not explicit_paths and not is_g_mode:
                paths = [b'.']
            elif not explicit_paths and is_g_mode:
                paths = [b'.']
            global_rulesets = determine_global_rules(opts)
            for p in paths:
                process_top_path(p, global_rulesets)
    finally:
        if opts.stats or opts.stats_only:
            elapsed = time.time() - START_TIME
            stats_text = ("%d matches\n%d files contained matches\n%d files searched\n%d bytes searched\n%.6f seconds\n" % (STATS.matches, STATS.files_contained, STATS.files_searched, STATS.bytes_searched, elapsed)).encode()
            WRITER.write(stats_text)
        WRITER.close()
    return 0 if ANY_FOUND else 1

def stat_module_is_stream(mode):
    return stat_is_fifo_or_reg(mode)

def stat_is_fifo_or_reg(mode):
    import stat as _st
    return _st.S_ISFIFO(mode) or _st.S_ISREG(mode)

if __name__ == '__main__':
    _argv = [os.fsencode(a) for a in sys.argv]
    try:
        _code = main(_argv)
    except ParseExit as _e:
        _code = _e.code
    except BrokenPipeError:
        _code = 1
    sys.exit(_code)
